css:
.quotation-print {
    width: 100%;
    font-family: Times;
    font-size: 14px;
    color: #000;
    line-height: 1.35;
    margin: 0;
    padding: 0;
}

@page {
    size: A4;
    margin: 10mm 12mm 10mm 12mm;
}

.letter-head {
    width: 100%;
    margin-bottom: 6px;
}

.top-date {
    width: 100%;
    text-align: right;
    font-size: 12px;
    font-weight: 700;
    margin: 4px 0 8px 0;
}

.quotation-title {
    text-align: center;
    font-size: 18px;
    font-weight: 700;
    display: inline-block;
    border-bottom: 1px solid #000;
    padding-bottom: 1px;
    line-height: 1.1;
    margin: 4px 0 20px 0;
}

.quotation-title-wrap {
    text-align: center;
    margin: 0 0 18px 0;
}

.quotation-ref {
    font-size: 14px;
    margin-bottom: 20px;
}

/*.greeting-line-straight {*/
/*    font-size: 13px;*/
/*    font-weight: 700;*/
/*    margin-bottom: 24px;*/
}

.opening-text {
    font-size: 13px;
    margin-bottom: 18px;
}

..quotation-table-exact {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
    margin-top: 10px;
    margin-bottom: 20px;
    font-family: Times;
    font-size: 13px;
    color: #000;
}

.quotation-table-exact th,
.quotation-table-exact td {
    border: 1px solid #000;
    /*padding: 16px 12px;*/
    vertical-align: top;
    text-align: left;
    word-wrap: break-word;
    overflow-wrap: break-word;
}

.quotation-table-exact th {
    font-weight: 700;
    text-align: left;
    line-height: 1.5;
    height: 92px;
    color: #000;
    padding: 12px 10px;
}

.quotation-table-exact td {
    line-height: 1.5;
    font-size: 13px;
    padding: 10px 10px;
}

.quotation-table-exact td:nth-child(1),
.quotation-table-exact td:nth-child(4),
.quotation-table-exact td:nth-child(5),
.quotation-table-exact td:nth-child(6),
.quotation-table-exact td:nth-child(7),
.quotation-table-exact td:nth-child(8),
.quotation-table-exact td:nth-child(9) {
    text-align: center;
}

.item-row td {
    height: 56px;
}

.name-cell {
    line-height: 1.6;
}

.total-row td {
    font-weight: 700;
    padding-top: 18px;
    padding-bottom: 18px;
}

.total-label {
    text-align: right !important;
    padding-right: 16px !important;
}

table, tr, td, th {
    page-break-inside: avoid;
}
.amount-words {
    font-size: 14px;
    margin-top: 10px;
    margin-bottom: 28px;
}

.closing-text {
    font-size: 14px;
    margin-bottom: 10px;
    line-height: 1.4;
}

.sincerely-text {
    font-size: 14px;
    margin-bottom: 30px;
    line-height: 1.4;
}

.signature-title {
    font-size: 14px;
    font-weight: 700;
    margin-bottom: 14px;
}

.signature-line {
    width: 220px;
    border-top: 1px solid #000;
    margin-top: 0;
}
table, tr, td, th {
    page-break-inside: avoid;
}

thead {
    display: table-header-group;
}

.greeting-line-straight {
    font-size: 14px;
    font-weight: 400;
    margin: 8px 0 4px 0;
    line-height: 1.2;
}

.customer-name-bold {
    font-weight: 700;
}

.opening-text {
    font-size: 14px;
    font-weight: 400;
    margin: 0 0 12px 0;
    line-height: 1.2;
}
